from dataclasses import dataclass, field

@dataclass
class CostTracker:
    in_tokens: int = 0
    out_tokens: int = 0
    price_in: float = {{price_in}}
    price_out: float = {{price_out}}

    def add(self, usage):
        self.in_tokens += usage.prompt_tokens
        self.out_tokens += usage.completion_tokens

    @property
    def usd(self) -> float:
        return self.in_tokens * self.price_in / 1e6 + self.out_tokens * self.price_out / 1e6

tracker = CostTracker()
